/* From Uiverse.io by Lakshay-art  - Tags: simple, animation, button, transition, click animation, bounce animation */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  border: none;
  /* margin: 0px !important; */
  background: transparent;
  transition: scale 1s;
}
.__UIV_SCOPE__ .button:hover {
  scale: 1.05;
}
.__UIV_SCOPE__ #main-border {
  border-radius: 22px;
  padding: 1px;
  background: linear-gradient(180deg, #e8e8e8, #d2d2d2);
  box-shadow: 0px 20px 25px #0002, 0px 3px 4px #0004;
}
.__UIV_SCOPE__ #main {
  /* border: 2px solid #e4e4e4; */
  border-radius: 21px;
  width: 260px;
  height: 90px;
  background: linear-gradient(180deg, #1111, #0007);
  padding: 4px;

  /* overflow: hidden; */
}
.__UIV_SCOPE__ #inner-box {
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #fff, #eaeaea);
  border-radius: 16px;
  box-shadow: 0px 2px 3px #0008;
  padding-block: 6px;
  padding-inline: 6px;
  position: relative;
}
.__UIV_SCOPE__ #inner-dent {
  border-radius: 35px;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #eaeaea 0%, #fff 70%);
  filter: blur(1.5px);
}
.__UIV_SCOPE__ #text-container {
  position: absolute;
  top: 0px;
  left: 0px;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
  gap: 75px;
  /* background-color: red; */
}
.__UIV_SCOPE__ #text {
  font-size: 24px;
  font-weight: 600;
}
.__UIV_SCOPE__ #text-container:focus > #arrow {
  transform: rotate(-45deg) translateX(110px) translateY(90px);
  /* transform: rotate(45deg) translateX(100px) translateY(-90px); */
  transition: transform 1s;
}
.__UIV_SCOPE__ #send {
  font-size: 24px;
  font-weight: 600;
  position: absolute;
  top: 0px;
  left: 57px;
  /* justify-content: center; */
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
}
.__UIV_SCOPE__ #text-container:focus {
  transform: translateY(-450px);
  transition: transform 1.5s 1s ease-in;
  /* background-color: red; */
}
.__UIV_SCOPE__ #inner-box:focus-within > #send {
  opacity: 0;
  transition: opacity 1s 1s;
}
.__UIV_SCOPE__ #sent {
  font-size: 24px;
  font-weight: 600;
  position: absolute;
  top: 0px;
  left: 57px;
  /* justify-content: center; */
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
  opacity: 0;
}

.__UIV_SCOPE__ #inner-box:focus-within > #sent {
  opacity: 1;
  transform: translateX(20px);
  transition: opacity 1s 1s, transform 1s 1s;
}

.__UIV_SCOPE__ #tick {
  position: absolute;
  top: 0px;
  right: 0px;
  /* justify-content: center; */
  align-items: center;
  /* width: 100%; */
  height: 100%;
  display: flex;
  opacity: 0;
}
.__UIV_SCOPE__ #inner-box:focus-within > #tick {
  opacity: 1;
  transform: translateX(-85px);
  transition: opacity 1s 1.3s, transform 1s 1s;
}
.__UIV_SCOPE__ .button:focus-within {
  animation: recoil 0.4s 0.9s;
  /* transform: translateY(10px);
  transition: transform 1s 0.8s; */
}

@keyframes recoil {
  0% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(10px);
  }
  100% {
    transform: translateY(0px);
  }
}
.__UIV_SCOPE__ #planebody {
  position: absolute;
  top: 22px;
  right: 62px;
  /* justify-content: center; */
  align-items: center;
  /* width: 100%; */
  height: 100%;
  display: flex;
  opacity: 0;
}
.__UIV_SCOPE__ #text-container:focus-within > #planebody {
  opacity: 1;
  /* transform: translateX(20px); */
  transition: opacity 1s 0.5s;
}
